// Parses the CSV export of the sheet into row objects. Handles quoted fields.
const config = $('Config (edit me)').first().json;
const raw = $input.first().json;

function parseCsv(text) {
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else { inQuotes = false; }
      } else { field += ch; }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === ',') {
      row.push(field); field = '';
    } else if (ch === '\n') {
      row.push(field); field = '';
      rows.push(row); row = [];
    } else if (ch !== '\r') {
      field += ch;
    }
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows.filter(r => r.some(c => String(c).trim() !== ''));
}

const text = typeof raw === 'string' ? raw : (raw.data ?? raw.body ?? '');
if (!String(text).trim()) {
  return [{ json: { rows: [], sheet_name: config.sheetName, error: 'Sheet returned no rows. Publish the sheet to the web, and check sheetId + sheetName in Config.' } }];
}

const table = parseCsv(String(text));
if (table.length < 2) {
  return [{ json: { rows: [], sheet_name: config.sheetName, error: 'Sheet has a header but no invoice rows.' } }];
}

const headers = table[0].map(h => String(h).trim());
const rows = table.slice(1).map(r => {
  const o = {};
  headers.forEach((h, i) => { o[h] = (r[i] ?? '').trim(); });
  return o;
});

return [{ json: { rows, sheet_name: config.sheetName, row_count: rows.length } }];

// Keeps invoices that are overdue AND under the reminder cap.
const config = $('Config (edit me)').first().json;
const parsed = $input.first().json;

if (parsed.error) {
  return [{ json: { due: [], error: parsed.error } }];
}

const after = Number(config.reminderAfterDays ?? 7);
const max = Number(config.maxReminders ?? 3);
const now = new Date();

const pick = (row, ...names) => {
  for (const n of names) {
    if (row[n] !== undefined && String(row[n]).trim() !== '') return String(row[n]).trim();
  }
  return '';
};

const due = [];
for (const row of parsed.rows || []) {
  const invoiceId = pick(row, 'invoice_id', 'invoice id', 'id', 'invoice');
  const clientName = pick(row, 'client_name', 'client', 'name');
  const clientEmail = pick(row, 'client_email', 'email');
  const amount = pick(row, 'amount', 'total');
  const currency = pick(row, 'currency') || config.currency || 'USD';
  const dueDate = pick(row, 'due_date', 'due', 'due date');
  const countRaw = pick(row, 'reminder_count', 'reminders');
  const reminderCount = Number(countRaw || 0);

  if (!invoiceId || !clientEmail || !dueDate) continue;

  const dueTime = new Date(dueDate);
  if (isNaN(dueTime.getTime())) continue;

  const daysOverdue = Math.floor((now.getTime() - dueTime.getTime()) / 86400000);
  if (daysOverdue < after) continue;
  if (!Number.isFinite(reminderCount) || reminderCount >= max) continue;

  due.push({
    invoice_id: invoiceId,
    client_name: clientName,
    client_email: clientEmail,
    amount,
    currency,
    due_date: dueDate,
    days_overdue: daysOverdue,
    reminder_count: reminderCount,
    next_reminder_number: reminderCount + 1,
    payment_link: String(config.paymentLinkBase || '') + invoiceId
  });
}

// One item per invoice, so the Loop Over Items node can walk them one by one.
return due.map((d) => ({ json: { ...d, due_count: due.length } }));

// Builds the reminder email. Tone escalates with the reminder number.
const config = $('Config (edit me)').first().json;
const inv = $input.first().json;

const n = Number(inv.next_reminder_number || 1);
const tier = n === 1 ? 1 : (n === 2 ? 2 : 3);

const subjectByTier = {
  1: `Friendly reminder — outstanding balance {{invoice_id}}`,
  2: `Second reminder — outstanding balance {{invoice_id}}`,
  3: `Final reminder — outstanding balance {{invoice_id}}`
};

const bodyByTier = {
  1: `Hi {{client_name}},

Just a friendly reminder that there is an outstanding balance of {{currency}} {{amount}} on your account, dated {{due_date}}.

If you've already paid, just reply to this email and we'll check.

Pay here: {{payment_link}}

Thanks,
{{biz_name}}`,
  2: `Hi {{client_name}},

A quick follow-up on the outstanding balance of {{currency}} {{amount}} on your account, dated {{due_date}}.

If you've already paid, reply and we'll check. If you'd like to set up a payment arrangement, reply and we'll work something out.

Pay here: {{payment_link}}

Thanks,
{{biz_name}}`,
  3: `Hi {{client_name}},

This is our final automated reminder about the outstanding balance of {{currency}} {{amount}} on your account, dated {{due_date}}.

If you need help or would like a payment arrangement, please reply — the practice manager would rather sort this out with you than let it sit.

Pay here: {{payment_link}}

Thanks,
{{biz_name}}`
};

const fill = (s) => String(s)
  .replace('{{client_name}}', inv.client_name || 'there')
  .replace('{{invoice_id}}', inv.invoice_id || '')
  .replace('{{amount}}', inv.amount || '')
  .replace('{{currency}}', inv.currency || '')
  .replace('{{due_date}}', inv.due_date || '')
  .replace('{{payment_link}}', inv.payment_link || '')
  .replace('{{biz_name}}', config.bizName || 'us');

return [{ json: {
  invoice_id: inv.invoice_id,
  client_email: inv.client_email,
  subject: fill(subjectByTier[tier]),
  body: fill(bodyByTier[tier]),
  tier,
  reminder_number: n,
  days_overdue: inv.days_overdue,
  payment_link: inv.payment_link,
  bcc: config.ownerBcc || ''
} }];

// Collects every reminder built during this run (the loop may run N times).
const sent = [];
for (const item of $('Build email').all()) {
  const j = item.json || {};
  if (j.invoice_id) sent.push({ invoice_id: j.invoice_id, client_email: j.client_email, tier: j.tier, reminder_number: j.reminder_number, subject: j.subject });
}
return [{ json: { sent_count: sent.length, sent } }];
